extends Node2D

enum GameState {
	PLAYING,
	GAME_OVER,
}

const SCREEN_WIDTH: float = 800.0
const SCREEN_HEIGHT: float = 600.0
const PLAYER_SPEED: float = 350.0
const HIT_DISTANCE: float = 40.0
const INITIAL_LIVES: int = 3
const INITIAL_SCORE: float = 0.0
const PLAYER_START_POSITION: Vector2 = Vector2(400.0, 500.0)

var state: GameState = GameState.PLAYING
var lives: int = INITIAL_LIVES
var score: float = INITIAL_SCORE
var high_score: float = INITIAL_SCORE

@onready var player: Sprite2D = $Player
@onready var score_label: Label = $ScoreLabel
@onready var lives_label: Label = $LivesLabel
@onready var record_label: Label = $RecordLabel
@onready var game_over_label: Label = $GameOverLabel
@onready var meteors: Array[Node] = [$Meteor1, $Meteor2, $Meteor3]


func _ready() -> void:
	game_over_label.visible = false
	_update_ui()


func _unhandled_input(event: InputEvent) -> void:
	if state == GameState.GAME_OVER and event.is_action_pressed("restart"):
		_restart_game()


func _process(delta: float) -> void:
	match state:
		GameState.PLAYING:
			score += delta
			_move_player(delta)
			_update_meteors(delta)
			_check_collisions()
			_update_ui()
		GameState.GAME_OVER:
			if Input.is_action_just_pressed("restart") or Input.is_action_pressed("restart"):
				_restart_game()


func _move_player(delta: float) -> void:
	var direction := Vector2.ZERO
	if Input.is_action_pressed("move_left"):
		direction.x -= 1.0
	if Input.is_action_pressed("move_right"):
		direction.x += 1.0
	if Input.is_action_pressed("move_up"):
		direction.y -= 1.0
	if Input.is_action_pressed("move_down"):
		direction.y += 1.0

	if direction != Vector2.ZERO:
		direction = direction.normalized()
		player.position += direction * PLAYER_SPEED * delta

	player.position.x = clampf(player.position.x, 0.0, SCREEN_WIDTH)
	player.position.y = clampf(player.position.y, 0.0, SCREEN_HEIGHT)


func _update_meteors(delta: float) -> void:
	for meteor in meteors:
		if meteor is Meteor:
			meteor.update_speed(score)
			meteor.move(delta)


func _check_collisions() -> void:
	for meteor in meteors:
		if meteor is Meteor:
			if player.position.distance_to(meteor.position) <= HIT_DISTANCE:
				lives -= 1
				meteor.reset_position()
				if lives <= 0:
					_trigger_game_over()
					break


func _trigger_game_over() -> void:
	state = GameState.GAME_OVER
	if score > high_score:
		high_score = score
	game_over_label.visible = true
	_update_ui()


func _restart_game() -> void:
	lives = INITIAL_LIVES
	score = INITIAL_SCORE
	player.position = PLAYER_START_POSITION
	for meteor in meteors:
		if meteor is Meteor:
			meteor.speed = Meteor.BASE_SPEED
			meteor.reset_position()
	game_over_label.visible = false
	state = GameState.PLAYING
	_update_ui()


func _update_ui() -> void:
	score_label.text = "Tempo: " + str(int(score)) + "s"
	lives_label.text = "Vite: " + str(lives)
	record_label.text = "Record: " + str(int(high_score)) + "s"

